import pytest
from pyresample.area_config import load_area_from_string

def test_load_area_from_string_invalid_keyword():
    # Valid area definition string
    # area_def_string = "area_id=test_area description='test description' proj_id='test_proj' crs='+proj=latlon' shape=(10, 10) area_extent=(-180, -90, 180, 90)"

    # Area definition string with an invalid keyword 'revolution'
    area_def_string = "area_id=test_area description='test description' proj_id='test_proj' crs='+proj=latlon' shape=(10, 10) area_extent=(-180, -90, 180, 90) revolution=123"

    try:
        load_area_from_string(area_def_string)
    except TypeError:
        print("Caught expected TypeError for invalid keyword")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
    else:
        print("Failed: load_area_from_string silently ignored the invalid keyword 'revolution'")
        exit(1)

if __name__ == "__main__":
    test_load_area_from_string_invalid_keyword()

